const $=id=>document.getElementById(id);const model=new DiffusionModel();let running=false;const field=$('field'),ctx=field.getContext('2d'),off=document.createElement('canvas');let map;
const colors=[[11,19,28],[38,67,78],[21,38,53],[34,58,82]];
function geometry(){off.width=model.nx;off.height=model.ny;map=off.getContext('2d').createImageData(model.nx,model.ny);$('geometryInfo').textContent=`Effective wall thickness: ${model.thickness.toFixed(3)} mm; ${model.sensors.length} sensors. Stable time step: ${model.dt.toPrecision(3)} s. Sources: ${model.sources.length}.`;}
function place(x,y){if($('mode').value==='remove'){let best=-1,dist=.25;model.sources.forEach((s,i)=>{const d=Math.hypot(s.x-x,s.y-y);if(d<dist){dist=d;best=i;}});if(best>=0)model.sources.splice(best,1);}else if(!model.addSource(x,y,$('mode').value,+$('strength').value)){$('notice').textContent='Place the source strictly inside the semicircle.';return;}$('notice').textContent='Source updated. Press Run to evolve the field.';draw();}
function transform(){const scale=Math.min((field.width-100)/8,(field.height-75)/(4-model.ymin));return{scale,left:(field.width-8*scale)/2,top:30};}
function draw(){let max=0;for(const c of model.c)max=Math.max(max,c);const ceiling=Math.max(max,1e-9),{scale,left,top}=transform(),px=x=>left+(x+4)*scale,py=y=>top+(4-y)*scale;
for(let j=0;j<model.ny;j++)for(let i=0;i<model.nx;i++){const a=j*model.nx+i,k=4*((model.ny-1-j)*model.nx+i),base=colors[model.kind[a]];let v=Math.log1p(99*model.c[a]/ceiling)/Math.log(100);map.data[k]=base[0]+v*(255-base[0]);map.data[k+1]=base[1]+v*(218-base[1]);map.data[k+2]=base[2]+v*(111-base[2]);map.data[k+3]=255;}off.getContext('2d').putImageData(map,0,0);ctx.clearRect(0,0,field.width,field.height);ctx.imageSmoothingEnabled=false;ctx.drawImage(off,left,top,8*scale,(4-model.ymin)*scale);
ctx.strokeStyle='#68878e';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(px(0),py(0),2*scale,Math.PI,2*Math.PI);ctx.stroke();ctx.fillStyle='#8b99a5';const y0=py(0),y1=py(-model.thickness);ctx.fillRect(px(-2),y0,4*scale,y1-y0);for(const cx of model.centers){ctx.clearRect(px(cx-model.p.hole/2),y0,model.p.hole*scale,y1-y0);ctx.drawImage(off,(cx-model.p.hole/2+4)/model.h,(4)/model.h,model.p.hole/model.h,model.wallRows,px(cx-model.p.hole/2),y0,model.p.hole*scale,y1-y0);}
ctx.font='13px Segoe UI';ctx.fillStyle='#8ba6b5';ctx.fillText('EXTERIOR · c = 0 at distant edges',px(-3.8),py(3.65));ctx.fillText('SEALED FLUID CHAMBER',px(-1.4),py(-model.thickness-.65));ctx.fillText('x (mm)',px(2.15),py(-.5));for(let x=-2;x<=2;x++){ctx.fillText(x.toFixed(0),px(x)-4,py(-model.thickness-.95));}ctx.strokeStyle='#a7c5c8';ctx.beginPath();ctx.moveTo(px(.25),py(1.45));ctx.lineTo(px(1.4),py(1.45));ctx.stroke();ctx.fillText('r = 2 mm',px(.35),py(1.55));
model.sensors.forEach((s,i)=>{ctx.fillStyle='#ffbd69';ctx.beginPath();ctx.arc(px(s.x),py(-model.thickness-model.h/2),3.5,0,Math.PI*2);ctx.fill();ctx.fillText(i+1,px(s.x)-4,py(-model.thickness-.2));});model.sources.forEach(s=>{ctx.strokeStyle='#f5fcff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px(s.x),py(s.y),7,0,Math.PI*2);ctx.moveTo(px(s.x)-11,py(s.y));ctx.lineTo(px(s.x)+11,py(s.y));ctx.moveTo(px(s.x),py(s.y)-11);ctx.lineTo(px(s.x),py(s.y)+11);ctx.stroke();});
$('maximum').textContent=max.toPrecision(3);$('time').textContent=model.time.toFixed(1);$('sourceCount').textContent=`${model.sources.length} source${model.sources.length===1?'':'s'}`;const profile=model.profileIndices.map(a=>model.c[a]),sensors=model.sensors.map(s=>model.c[s.index]);const ymax=Math.max(...profile,...sensors,1e-6)*1.12;plot('profile',profile,ymax,false);plot('sensors',sensors,ymax,true);}
function plot(id,values,max,bars){const cv=$(id),c=cv.getContext('2d'),w=cv.width,h=cv.height,l=72,r=20,t=28,b=49,pw=w-l-r,ph=h-t-b;c.clearRect(0,0,w,h);c.font='13px Segoe UI';for(let k=0;k<=4;k++){let y=t+ph*k/4;c.strokeStyle='#293d4b';c.beginPath();c.moveTo(l,y);c.lineTo(w-r,y);c.stroke();c.fillStyle='#99b0c0';c.fillText((max*(1-k/4)).toExponential(1),2,y+4);}c.fillStyle='#99b0c0';c.fillText('c (a.u.)',4,14);if(bars){values.forEach((v,i)=>{const bw=pw/values.length;c.fillStyle='#efb974';c.fillRect(l+(i+.17)*bw,t+ph*(1-v/max),bw*.66,ph*v/max);c.fillStyle='#99b0c0';c.fillText(i+1,l+(i+.4)*bw,h-28);});c.fillText('Sensor number · left → right',l+pw/2-85,h-6);}else{c.strokeStyle='#78e1ce';c.lineWidth=2;c.beginPath();values.forEach((v,i)=>{const x=l+pw*(i+.5)/values.length,y=t+ph*(1-v/max);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();for(let k=-2;k<=2;k++)c.fillText(k,l+pw*(k+2)/4-4,h-28);c.fillText('Position along diameter, x (mm)',l+pw/2-95,h-6);}}
field.addEventListener('click',e=>{const r=field.getBoundingClientRect(),{scale,left,top}=transform();place(((e.clientX-r.left)*field.width/r.width-left)/scale-4,4-((e.clientY-r.top)*field.height/r.height-top)/scale);});$('add').onclick=()=>place(+$('sourceX').value,+$('sourceY').value);
function play(){running=!running;$('play').textContent=running?'Ⅱ Pause':'▶ Run';$('state').textContent=running?'RUNNING':'PAUSED';}$('play').onclick=play;$('step').onclick=()=>{if(running)play();model.step();draw();};$('reset').onclick=()=>{model.reset();geometry();draw();};$('clear').onclick=()=>{model.sources=[];model.reset();geometry();draw();};
for(const key of ['inside','fluid','outside','thickness','hole','spacing'])$(key).addEventListener('change',()=>{const value=+$(key).value;if(!Number.isFinite(value)||value<+$(key).min||value>+$(key).max){$(key).value=model.p[key];return;}let p={...model.p,[key]:value};if(p.hole>=p.spacing){$('notice').textContent='Hole width must be smaller than center spacing.';$(key).value=model.p[key];return;}model.p=p;model.reset();geometry();outputs();draw();$('notice').textContent='Geometry / medium updated; concentration field reset.';});function outputs(){for(const id of ['thickness','hole','spacing'])$(id+'Value').textContent=(+$(id).value).toFixed(3);$('speedValue').textContent=$('speed').value+' steps / frame';}$('speed').oninput=outputs;
$('export').onclick=()=>{let csv='type,x_mm,concentration_au,time_s\n';model.profileIndices.forEach((a,i)=>csv+=`profile,${-2+(i+.5)*model.h},${model.c[a]},${model.time}\n`);model.sensors.forEach(s=>csv+=`sensor,${s.x},${model.c[s.index]},${model.time}\n`);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='diffusion-readout.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function animate(){if(running){const start=performance.now();for(let i=0;i<+$('speed').value;i++){model.step();if(performance.now()-start>24)break;}draw();}requestAnimationFrame(animate);}geometry();outputs();draw();animate();
